fn generous()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:16777216,maximum_capacity_bytes:16777216,maximum_release_bytes:16777216,maximum_depth:256}}
fn exact(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn observed<T>(g:RetainedCloneGrant,operation:impl FnOnce()->(T,RetainedCloneProgress))->T{let((result,p),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(operation);assert!(p.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result}
fn deny(d:RetirementDemand,mut operation:impl FnMut(RetainedCloneGrant)->RetainedCloneProgress){for axis in 0..5{let mut g=exact(d);let value=match axis{0=>&mut g.maximum_items,1=>&mut g.maximum_copy_bytes,2=>&mut g.maximum_capacity_bytes,3=>&mut g.maximum_release_bytes,_=>&mut g.maximum_depth};if *value==0{continue}*value-=1;let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||operation(g));assert_eq!(p,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}}
